CREATE TABLE "Agent" ("id" TEXT NOT NULL PRIMARY KEY, "displayName" TEXT NOT NULL, "source" TEXT NOT NULL, "repositoryOwner" TEXT, "repositoryName" TEXT, "issueNumber" INTEGER, "pullRequestNumber" INTEGER, "taskTitle" TEXT, "taskUrl" TEXT, "status" TEXT NOT NULL, "statusReason" TEXT, "statusConfidence" REAL NOT NULL DEFAULT 1, "statusKind" TEXT NOT NULL DEFAULT 'mock', "lastActivityAt" DATETIME, "startedAt" DATETIME, "completedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, "metadata" TEXT NOT NULL DEFAULT '{}');
CREATE TABLE "AgentActivity" ("id" TEXT NOT NULL PRIMARY KEY, "agentId" TEXT NOT NULL, "kind" TEXT NOT NULL, "summary" TEXT NOT NULL, "occurredAt" DATETIME NOT NULL, "url" TEXT, CONSTRAINT "AgentActivity_agentId_fkey" FOREIGN KEY ("agentId") REFERENCES "Agent" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Desk" ("id" TEXT NOT NULL PRIMARY KEY, "agentId" TEXT NOT NULL, "row" INTEGER NOT NULL, "column" INTEGER NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "reservedUntil" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Desk_agentId_fkey" FOREIGN KEY ("agentId") REFERENCES "Agent" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "AvatarProfile" ("agentId" TEXT NOT NULL PRIMARY KEY, "color" TEXT NOT NULL, "accessory" TEXT NOT NULL DEFAULT 'none', "seed" INTEGER NOT NULL, CONSTRAINT "AvatarProfile_agentId_fkey" FOREIGN KEY ("agentId") REFERENCES "Agent" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ProviderSnapshot" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" TEXT NOT NULL, "healthy" BOOLEAN NOT NULL, "stale" BOOLEAN NOT NULL DEFAULT false, "message" TEXT NOT NULL, "lastSuccessAt" DATETIME, "rateLimitResetAt" DATETIME, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "AppSetting" ("key" TEXT NOT NULL PRIMARY KEY, "value" TEXT NOT NULL, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "Desk_agentId_key" ON "Desk"("agentId");
CREATE UNIQUE INDEX "Desk_row_column_key" ON "Desk"("row", "column");
CREATE INDEX "AgentActivity_agentId_occurredAt_idx" ON "AgentActivity"("agentId", "occurredAt");
